import { z } from 'zod';
import { SkillCreationContext, SkillTelemetryEvent } from './skill-telemetry';
import { SkillInstallModelConfig, SkillReviewLocale } from './skill-install-config';
import { UserSkillId } from './skill-identity';
import { SkillWorkflow } from './skill-workflow';

const Id = z.string().min(1).max(200).regex(/^[a-zA-Z0-9_-]+$/);
const Hash = z.string().regex(/^[a-f0-9]{64}$/);
/** Legacy persisted metadata only; there are no project operations in this release. */
export const Project = z.object({ projectId: Id, name: z.string().trim().min(1).max(120)
  .regex(/^[^\r\n\0]+$/), createdAt: z.number(), updatedAt: z.number() }).strict();
export type Project = z.infer<typeof Project>;
export const SkillTarget = z.discriminatedUnion('scope', [
  z.object({ scope: z.literal('user') }).strict(),
  z.object({ scope: z.literal('project'), projectId: Id }).strict(),
]);
export type SkillTarget = z.infer<typeof SkillTarget>;
export const SkillPackageSource = z.discriminatedUnion('type', [
  z.object({ type: z.literal('folder'), path: z.string().min(1).max(4096) }).strict(),
  z.object({ type: z.literal('zip'), path: z.string().min(1).max(4096), fileName: z.string().optional() }).strict(),
  z.object({ type: z.literal('git'), url: z.string().min(1).max(2048), ref: z.string().min(1).max(200).optional(),
    subdir: z.string().max(1024).optional() }).strict(),
  z.object({ type: z.literal('draft'), draftId: Id, draftRevisionId: Id }).strict(),
]);
export type SkillPackageSource = z.infer<typeof SkillPackageSource>;
export const SkillAnalysis = z.object({
  purpose: z.string().max(4000), inputs: z.array(z.string()), outputs: z.array(z.string()),
  triggers: z.array(z.string()), root: z.string(), scripts: z.array(z.string()), references: z.array(z.string()),
  assets: z.array(z.string()), dependencies: z.array(z.string()), issues: z.array(z.string()),
  verdict: z.enum(['approve', 'repair', 'reject', 'unverifiable']), reason: z.string().max(4000),
  validation: z.literal('static-only'),
}).strict();
export type SkillAnalysis = z.infer<typeof SkillAnalysis>;
export const SkillRepairFailure = z.object({
  reason: z.enum(['protected-file', 'unreviewed-file', 'invalid-edit', 'file-too-large', 'conflicting-edits', 'renamed-skill']),
  path: z.string().max(1024).optional(),
}).strict();
export type SkillRepairFailure = z.infer<typeof SkillRepairFailure>;
export const SkillFileChange = z.object({ path: z.string(), before: z.string(), after: z.string(),
  origin: z.enum(['reviewer', 'runtime']) }).strict();
export type SkillFileChange = z.infer<typeof SkillFileChange>;
export const SkillPackageFile = z.object({ path: z.string().min(1).max(1024), bytes: z.number().int().nonnegative() }).strict();
export const SkillRevision = z.object({
  revisionId: Id, instanceId: Id, packageSha256: Hash, systemSha256: Hash, installedSha256: Hash,
  /** Relative to the Runtime data root. */
  contentPath: z.string().min(1), createdAt: z.number(), kind: z.enum(['install', 'update', 'policy', 'migration']),
  changes: z.array(SkillFileChange), analysis: SkillAnalysis.optional(), workflow: SkillWorkflow.optional(),
  files: z.array(SkillPackageFile).max(5000).optional(),
}).strict();
export type SkillRevision = z.infer<typeof SkillRevision>;
export const SkillInstance = z.object({
  instanceId: Id, name: UserSkillId, displayName: z.string(), description: z.string(), target: SkillTarget,
  // allowImplicitInvocation is retained for persisted/RPC compatibility; imported Skills always allow it.
  enabled: z.boolean(), allowImplicitInvocation: z.boolean(), activeRevisionId: Id,
  source: SkillPackageSource, subdir: z.string(), trackingRef: z.string().optional(), resolvedCommit: z.string().optional(),
  originalSha256: Hash, installationId: Id, installedAt: z.number(), updatedAt: z.number(), validation: z.literal('static-only'),
  /** Latest successful package install/update; status and policy changes do not advance it. */
  lastInstalledAt: z.number().optional(),
}).strict();
export type SkillInstance = z.infer<typeof SkillInstance>;
/** Runtime-confirmed calls in the rolling last 30 days, across an instance's revisions.
 * unknown retains confirmed legacy calls whose invocation mode was not persisted. */
export const SkillInvocationSummary = z.object({
  total: z.number().int().nonnegative(), explicit: z.number().int().nonnegative(),
  implicit: z.number().int().nonnegative(), unknown: z.number().int().nonnegative(),
  lastInvokedAt: z.number().int().nonnegative().nullable(), available: z.boolean(),
}).strict();
export type SkillInvocationSummary = z.infer<typeof SkillInvocationSummary>;
/** Completed leaf steps remain revision-scoped; invocation counts are independent. */
export const SkillUseSummary = z.object({ revisionId: Id, lastCompletedAt: z.number().int().nonnegative().nullable(), completedTurns: z.number().int().nonnegative(), invocations: SkillInvocationSummary }).strict();
export type SkillUseSummary = z.infer<typeof SkillUseSummary>;

export const EffectiveSkill = z.object({
  instanceId: Id, revisionId: Id, name: z.string(), displayName: z.string(), description: z.string(),
  origin: z.enum(['official', 'imported']), scope: z.enum(['official', 'user', 'project']), projectId: Id.optional(),
  sourceType: z.enum(['bundled', 'folder', 'zip', 'git', 'draft']), path: z.string().min(1), allowImplicitInvocation: z.boolean(),
}).strict();
export type EffectiveSkill = z.infer<typeof EffectiveSkill>;
export const SkillQuota = z.object({ pendingTasks: z.number().int().nonnegative(), stagedBytes: z.number().int().nonnegative(),
  reservedBytes: z.number().int().nonnegative(), maxPendingTasks: z.number().int().positive(), maxStagedBytes: z.number().int().positive(),
  cleanableInstallationIds: z.array(Id) }).strict();
export type SkillQuota = z.infer<typeof SkillQuota>;
export const SKILL_INSTALLATION_STATES = ['preparing', 'staging', 'awaiting-selection', 'awaiting-analysis-authorization',
  'analyzing', 'repairing', 'awaiting-confirmation', 'committing', 'refreshing', 'succeeded',
  'partially-succeeded', 'failed', 'cancelled', 'expired'] as const;
export const SKILL_TERMINAL_STATES = ['succeeded', 'partially-succeeded', 'failed', 'cancelled', 'expired'] as const;
export const SkillInstallCandidate = z.object({
  candidateId: Id, subdir: z.string(), name: z.string(), description: z.string(),
  state: z.enum(['pending', 'validating', 'analyzing', 'repairing', 'ready', 'failed', 'installed', 'skipped']),
  message: z.string(), errorCode: z.string().optional(), failureKind: z.enum(['content', 'process']).optional(), originalSha256: Hash.optional(),
  packageSha256: Hash.optional(), systemSha256: Hash.optional(), installedSha256: Hash.optional(),
  analysis: SkillAnalysis.optional(), repairFailure: SkillRepairFailure.optional(), workflow: SkillWorkflow.optional(), changes: z.array(SkillFileChange), tokensUsed: z.number().int().nonnegative(),
  files: z.array(SkillPackageFile).max(5000).optional(),
  /** One installation entry with source modules kept as local documents. */
  modules: z.array(z.object({ name: z.string(), entry: z.string(), description: z.string() }).strict()).optional(),
  /** Runtime-generated token binds both hashes, target and expected revision. */
  confirmationToken: z.string().optional(), instanceId: Id.optional(), revisionId: Id.optional(),
}).strict();
export type SkillInstallCandidate = z.infer<typeof SkillInstallCandidate>;
export const SkillDownloadProgress = z.object({
  phase: z.enum(['listing', 'archive', 'extracting', 'files', 'fallback', 'complete']),
  downloadedFiles: z.number().int().nonnegative(), totalFiles: z.number().int().nonnegative(),
  completedBytes: z.number().int().nonnegative(), totalBytes: z.number().int().nonnegative(),
  networkBytes: z.number().int().nonnegative(), networkTotalBytes: z.number().int().nonnegative().optional(),
  repositoryBytes: z.number().int().nonnegative(), cachedFiles: z.number().int().nonnegative(),
}).strict();
export type SkillDownloadProgress = z.infer<typeof SkillDownloadProgress>;
export const SkillBundleProgress = z.object({
  phase: z.enum(['copying', 'finalizing', 'complete']),
  copiedFiles: z.number().int().nonnegative(), totalFiles: z.number().int().nonnegative(),
  copiedBytes: z.number().int().nonnegative(), totalBytes: z.number().int().nonnegative(),
}).strict();
export type SkillBundleProgress = z.infer<typeof SkillBundleProgress>;
export const SkillInstallTask = z.object({
  installationId: Id, state: z.enum(SKILL_INSTALLATION_STATES), source: SkillPackageSource, target: SkillTarget,
  locale: SkillReviewLocale.optional(),
  expectedInstanceId: Id.optional(), expectedRevisionId: Id.optional(), analysisAttemptId: Id.optional(),
  modelConfig: SkillInstallModelConfig, candidates: z.array(SkillInstallCandidate), selectedCandidateIds: z.array(Id),
  resolvedCommit: z.string().optional(), trackingRef: z.string().optional(),
  downloadProgress: SkillDownloadProgress.optional(),
  bundleProgress: SkillBundleProgress.optional(),
  tokensUsed: z.number().int().nonnegative(), message: z.string(), errorCode: z.string().optional(),
  reviewRequestsUsed: z.number().int().nonnegative().optional(),
  reviewInputBytesUsed: z.number().int().nonnegative().optional(),
  reviewInitialRequestsUsed: z.number().int().nonnegative().optional(),
  reviewRetryRequestsUsed: z.number().int().nonnegative().optional(),
  reviewInitialInputBytesUsed: z.number().int().nonnegative().optional(),
  reviewRetryInputBytesUsed: z.number().int().nonnegative().optional(),
  createdAt: z.number(), updatedAt: z.number(), expiresAt: z.number(), cleanupPending: z.boolean(), validation: z.literal('static-only'),
  /** Cleared from the UI; retain the journal for provenance and billing attribution. */
  clearedAt: z.number().int().nonnegative().optional(),
}).strict();
export type SkillInstallTask = z.infer<typeof SkillInstallTask>;

/** Workspace-relative submission directory; the filesystem boundary is checked again by Runtime. */
export const SkillDraftPath = z.string().max(1024).regex(/^skill-drafts\/[a-zA-Z0-9][a-zA-Z0-9_-]*$/);
export const SkillDraftBase = z.object({ instanceId: Id, revisionId: Id, packageSha256: Hash }).strict();
export type SkillDraftBase = z.infer<typeof SkillDraftBase>;
export const SkillDraftRevisionState = z.enum(['ready', 'installing', 'installed', 'superseded', 'deleted']);
export type SkillDraftRevisionState = z.infer<typeof SkillDraftRevisionState>;
export const SkillDraftRevision = z.object({
  draftRevisionId: Id, revisionNumber: z.number().int().positive(), sourceTurnId: Id, contentSha256: Hash,
  sourcePath: SkillDraftPath, name: UserSkillId, displayName: z.string().min(1).max(200),
  description: z.string().max(4000), summary: z.string().max(4000), exampleTask: z.string().max(4000).optional(),
  hasScripts: z.boolean(), files: z.array(SkillPackageFile).max(5000), base: SkillDraftBase.optional(),
  rebasedFrom: SkillDraftBase.nullable().optional(), state: SkillDraftRevisionState,
  installationId: Id.optional(), installedInstanceId: Id.optional(), installedRevisionId: Id.optional(),
  creation: SkillCreationContext.extend({ submissionAttemptId: Id.optional(), submissionIndex: z.number().int().positive().optional() }).optional(),
  createdAt: z.number().int().nonnegative(),
}).strict();
export type SkillDraftRevision = z.infer<typeof SkillDraftRevision>;
export const SkillDraft = z.object({
  draftId: Id, threadId: Id, stateVersion: z.number().int().positive(), latestRevisionId: Id,
  revisions: z.array(SkillDraftRevision).min(1), boundInstanceId: Id.optional(),
  writeback: z.object({ status: z.enum(['synced', 'merge-required', 'failed']), changedFiles: z.number().int().nonnegative(),
    installedRevisionId: Id, reason: z.string().max(4000).optional() }).strict().optional(),
  deleted: z.boolean(), createdAt: z.number().int().nonnegative(), updatedAt: z.number().int().nonnegative(),
}).strict();
export type SkillDraft = z.infer<typeof SkillDraft>;
export const SkillCaptureSteps = z.array(z.string().trim().min(1).max(24)).min(2).max(4);
export const SkillCaptureSuggestion = z.object({
  suggestionId: Id.optional(),
  threadId: Id, turnId: Id, title: z.string().min(1).max(80), summary: z.string().min(1).max(400),
  reason: z.string().min(1).max(400), state: z.enum(['shown', 'accepted', 'dismissed']),
  steps: SkillCaptureSteps.optional(),
  createdAt: z.number().int().nonnegative(), updatedAt: z.number().int().nonnegative(),
}).strict();
export type SkillCaptureSuggestion = z.infer<typeof SkillCaptureSuggestion>;
export const SkillDraftComparison = z.object({
  instanceId: Id, revisionId: Id, baselineChanged: z.boolean(), nameBefore: z.string(), descriptionBefore: z.string(),
  files: z.array(z.object({ path: z.string(), kind: z.enum(['added', 'removed', 'modified']), before: z.string().optional(), after: z.string().optional() }).strict()).max(10000),
  scriptsAdded: z.array(z.string()), scriptsRemoved: z.array(z.string()), previousAnalysis: SkillAnalysis.optional(), previousWorkflow: SkillWorkflow.optional(), previousUse: SkillUseSummary.optional(),
}).strict();
export type SkillDraftComparison = z.infer<typeof SkillDraftComparison>;
export const skillCreationMethods = {
  'skills/prepareCreation': { params: z.object({ threadId: Id, context: SkillCreationContext }).strict(), result: z.object({ prepared: z.boolean() }).strict() },
  'skills/telemetryPending': { params: z.object({ since: z.number().int().nonnegative().optional() }).strict().optional(), result: z.object({ events: z.array(SkillTelemetryEvent).max(200) }).strict() },
  'skills/telemetryAck': { params: z.object({ eventIds: z.array(Id).max(200) }).strict(), result: z.object({ acknowledged: z.boolean() }).strict() },
  'skills/drafts': { params: z.object({ threadId: Id.optional() }).strict().optional(), result: z.object({ drafts: z.array(SkillDraft) }).strict() },
  'skills/draftDetail': { params: z.object({ draftId: Id, draftRevisionId: Id }).strict(),
    result: z.object({ draft: SkillDraft, revision: SkillDraftRevision, files: z.array(SkillPackageFile.extend({ text: z.string().optional() })), comparison: SkillDraftComparison.optional() }).strict() },
  'skills/deleteDraft': { params: z.object({ draftId: Id, expectedStateVersion: z.number().int().positive() }).strict(), result: z.object({ draft: SkillDraft }).strict() },
  'skills/installDraft': { params: z.object({ draftId: Id, draftRevisionId: Id, locale: SkillReviewLocale.optional() }).strict(),
    result: z.object({ installationId: Id, installation: SkillInstallTask, draft: SkillDraft }).strict() },
  'skills/captureSuggestions': { params: z.object({ threadId: Id }).strict(), result: z.object({ suggestions: z.array(SkillCaptureSuggestion) }).strict() },
  'skills/resolveSuggestion': { params: z.object({ threadId: Id, turnId: Id, action: z.enum(['accepted', 'dismissed']) }).strict(), result: z.object({ suggestion: SkillCaptureSuggestion }).strict() },
} as const;

/** Completed records consume no task quota unless retry data or cleanup residue is retained. */
export function skillInstallationUsesStaging(task: SkillInstallTask): boolean {
  if (task.clearedAt !== undefined && !task.cleanupPending && (SKILL_TERMINAL_STATES as readonly string[]).includes(task.state)) return false;
  return !(SKILL_TERMINAL_STATES as readonly string[]).includes(task.state) || task.cleanupPending
    || task.errorCode === 'SKILL_RECOVERY_REQUIRED'
    || task.candidates.some(candidate => candidate.state === 'failed' && Boolean(candidate.confirmationToken));
}

/** Main-only identity; never accepted from Renderer or persisted inside a package. */
export const SkillAnalysisAuthorization = z.object({
  installationId: Id, analysisAttemptId: Id, attemptToken: z.string().min(32).max(200),
  proxyCredential: z.string().min(32).max(200), candidateIds: z.array(Id).min(1).max(50), expiresAt: z.number(),
}).strict();
export type SkillAnalysisAuthorization = z.infer<typeof SkillAnalysisAuthorization>;
export const SKILL_INSTALL_HEADERS = Object.freeze({ attempt: 'x-hi3d-install-attempt',
  candidate: 'x-hi3d-install-candidate', round: 'x-hi3d-install-round', batch: 'x-hi3d-install-batch' });
export type TrustedModelRequestContext = { kind: 'chat' } | { kind: 'skill-install'; installationId: string;
  analysisAttemptId: string; candidateId: string; reviewRound: number; ownerId: string; environment: string };

export const SkillReleasePolicy = z.object({
  schema: z.literal('hi3d.skills-policy.v1'), revision: z.string().min(1).max(200),
  environment: z.enum(['test', 'pre', 'prod']), importEnabled: z.boolean(), analysisEnabled: z.boolean(), commitEnabled: z.boolean(),
  issuedAt: z.number().int(), expiresAt: z.number().int(),
}).strict();
export type SkillReleasePolicy = z.infer<typeof SkillReleasePolicy>;
export const SKILL_POLICY_MAX_CACHE_MS = 60_000;
export const SkillLocalReleaseState = z.object({ importEnabled: z.boolean(), analysisEnabled: z.boolean(), commitEnabled: z.boolean() }).strict();

/** A global scope overlaps every workspace; project leases include membership changes. */
export type SkillUpdateScope = { type: 'global' } | { type: 'project'; projectId: string } | { type: 'workspace'; assetId: string };
export interface SkillUpdateLease { readonly scopes: readonly SkillUpdateScope[]; release(): void }
export interface SkillTurnReservation { started(turnId: string): void; failed(): void }
export interface SkillStateGate {
  acquireUpdate(scopes: readonly SkillUpdateScope[], affectedWorkspaceIds?: readonly string[]): Promise<SkillUpdateLease>;
  reserveTurn(workspaceId: string, projectId: string | null, threadId: string): SkillTurnReservation;
  assertAvailable(workspaceId: string, projectId: string | null): void;
  completeTurn(threadId: string, turnId: string): void;
  blockRecovery(scopes: readonly SkillUpdateScope[], reason: string): void;
  finishRecovery(scopes: readonly SkillUpdateScope[]): void;
}

const InstanceMutation = z.object({ instanceId: Id, expectedRevisionId: Id });
const TaskId = z.object({ installationId: Id });
export const skillCommunityMethods = {
  'skills/installations': { params: z.object({}).optional(), result: z.object({ installations: z.array(SkillInstallTask), quota: SkillQuota }) },
  'skills/clearInstallLog': { params: TaskId.strict(), result: z.object({ installation: SkillInstallTask }) },
  'skills/setCandidateName': { params: TaskId.extend({ candidateId: Id, name: UserSkillId }).strict(), result: z.object({ installation: SkillInstallTask }) },
  'skills/analyzeInstall': { params: TaskId.extend({ candidateIds: z.array(Id).min(1).max(50), locale: SkillReviewLocale.optional() }).strict(), result: z.object({ installation: SkillInstallTask }) },
  'skills/effective': { params: z.union([z.object({ threadId: Id }).strict(), z.object({ assetId: Id }).strict()]),
    result: z.object({ skills: z.array(EffectiveSkill), assetId: Id, generation: z.number().int().nonnegative() }) },
  'skills/detail': { params: z.object({ instanceId: Id }).strict(), result: z.object({ skill: SkillInstance, revision: SkillRevision,
    installationIds: z.array(Id), usage: SkillUseSummary.optional() }) },
  'skills/setEnabled': { params: InstanceMutation.extend({ enabled: z.boolean() }).strict(), result: z.object({ skill: SkillInstance }) },
  /** Legacy clients are accepted, but the policy is always enabled. */
  'skills/setInvocationPolicy': { params: InstanceMutation.extend({ allowImplicitInvocation: z.boolean() }).strict(), result: z.object({ skill: SkillInstance }) },
  'skills/repair': { params: InstanceMutation.strict(), result: z.object({ skill: SkillInstance }) },
  'skills/checkUpdate': { params: z.object({ instanceId: Id }).strict(), result: z.object({ instanceId: Id,
    status: z.enum(['available', 'current', 'fixed', 'reselect-source']), resolvedCommit: z.string().optional(), trackingRef: z.string().optional() }) },
  'skills/prepareUpdate': { params: InstanceMutation.extend({ source: SkillPackageSource, subdir: z.string().max(1024).optional(), locale: SkillReviewLocale.optional() }).strict(),
    result: z.object({ installationId: Id, installation: SkillInstallTask }) },
} as const;
